import unittest
from allocation import allocate

class Allocation(unittest.TestCase):
    def test_remainders(self):
        weights=[1,1,1]
        self.assertEqual(allocate(2,weights),[1,1,0])
        self.assertEqual(allocate(-2,weights),[-1,-1,0])
        self.assertEqual(weights,[1,1,1])
        self.assertEqual(allocate(7,[0,2,1]),[0,5,2])
        self.assertEqual(allocate(0,[3,1]),[0,0])
        self.assertEqual(allocate(10,[2,3,5]),[2,3,5])
    def test_large_and_conservation(self):
        self.assertEqual(allocate(10**30+1,[1,1]),[5*10**29+1,5*10**29])
        for total in range(-19,20):
            shares=allocate(total,[3,7,2,0])
            self.assertEqual(sum(shares),total)
            self.assertEqual(shares[3],0)
    def test_invalid(self):
        for weights in [[],[0,0],[-1,4]]:
            with self.assertRaises(ValueError): allocate(9,weights)

if __name__ == '__main__':
    unittest.main()
